    // ==================== LIFECYCLE ====================
    protected override async Task OnInitializedAsync()
    {
        await LoadLevelFromStorage();
        maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JS);
        var result = await SessionStorage.GetAsync<UserSession>("UserSession");
        if (result.Success) currentSession = result.Value;

        thData.danhSachKhoiList = await TruongService.hGetDanhSachKhoi(maTruongBo, selectedCapHoc);
        thData.danhSachLopList = await TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc, SelectedNamHoc);
        thData.danhSachMonHocList = await DaoTaoService.hGetMonHoc(selectedCapHoc);
        thData.truong = await TruongService.hThongTinTruongByID(maTruongBo);
        thData.danhSachGiaoVienList = await TruongService.hGetDanhSachGiaoVien(maTruongBo, SelectedNamHoc);
    }

    protected override async Task OnParametersSetAsync()
    {
        Console.WriteLine($"[CKView] OnParametersSetAsync: Lop='{SelectedLop}', Mon='{SelectedMonHoc}', Ky='{SelectedHocKy}'");

        // LUÔN load học sinh khi có lớp (không phụ thuộc vào môn học)
        if (!string.IsNullOrEmpty(SelectedLop))
        {
            await LoadHocSinhData();
        }

        // Chỉ load đánh giá và trạng thái khóa khi có cả lớp và môn
        if (!string.IsNullOrEmpty(SelectedLop) && !string.IsNullOrEmpty(SelectedMonHoc))
        {
            await LoadLockStatus();
            await LoadDanhGiaData();
            modifiedStudents.Clear(); // Reset khi chuyển lớp/môn
        }
        else
        {
            // Nếu thiếu môn học, reset dữ liệu đánh giá nhưng giữ danh sách học sinh
            danhGiaCache.Clear();
            isSystemLocked = false;
            isClassSubjectLocked = false;
            Console.WriteLine($"[CKView] Bỏ qua load đánh giá vì thiếu MonHoc");
        }

        StateHasChanged();
    }

    private async Task LoadLevelFromStorage()
    {
        try
        {
            selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");
            selectedTenCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevelText");
            if (string.IsNullOrEmpty(selectedCapHoc))
            {
                selectedCapHoc = "02";
                selectedTenCapHoc = "Cấp Tiểu học";
                await BrowserStorageService.SetItem(JS, "selectedLevel", selectedCapHoc);
                await BrowserStorageService.SetItem(JS, "selectedLevelText", selectedTenCapHoc);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi đọc cấp học: {ex.Message}");
            selectedCapHoc = "02";
            selectedTenCapHoc = "Cấp Tiểu học";
        }
    }

    // ==================== LOCK STATUS ====================
    private async Task LoadLockStatus()
    {
        try
        {
            isSystemLocked = false;
            isClassSubjectLocked = false;

            DateTime now = DateTime.Now;
            int namHocInt = int.Parse(SelectedNamHoc.Split('-')[0]);
            int hocKyInt = int.Parse(SelectedHocKy);
            string currentNamHoc = await BrowserStorageService.GetItem(JS, "currentNamHoc") ?? "2025-2026";

            thoiGianNhapDiems = await DiemService.hGetThoiGianNhapDiem(
                namHocInt,
                hocKyInt,
                selectedCapHoc!,
                maTruongBo!
            );

            bool isInTimeRange = thoiGianNhapDiems.Any(x =>
                x.TrangThai == 1 &&
                now >= x.ThoiGianBatDau &&
                now <= x.ThoiGianKetThuc
            );
            isSystemLocked = !isInTimeRange;

            if (!string.IsNullOrEmpty(SelectedLopId) && !string.IsNullOrEmpty(SelectedMonHoc))
            {
                khoaSoDiems = await DiemService.hGetKhoaSoDiem(
                    selectedCapHoc!,
                    maTruongBo!,
                    currentNamHoc,
                    hocKyInt,
                    Convert.ToInt32(SelectedLopId)
                );

                isClassSubjectLocked = khoaSoDiems.Any(x =>
                    x.IdLopBo == SelectedLopId &&
                    x.IdMonHoc == SelectedMonHoc &&
                    x.IsLock
                );
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi LoadLockStatus: {ex.Message}");
            isSystemLocked = true;
            isClassSubjectLocked = true;
        }
        finally
        {
            StateHasChanged();
        }
    }

