    // ==================== DATA LOADING ====================
    private async Task LoadHocSinhData()
    {
        if (!string.IsNullOrEmpty(SelectedLop) && !string.IsNullOrEmpty(SelectedNamHoc))
        {
            try
            {
                hocSinhList = await TruongService.hGetHocSinhByLop(maTruongBo, SelectedLop, SelectedNamHoc);
                hocSinhList = hocSinhList.OrderBy(hs => hs.SoThuTu).ToList();
                filteredHocSinhList = hocSinhList.ToList(); // Cho modal in
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Lỗi tải học sinh: {ex.Message}");
                hocSinhList = new List<HocSinhDTO>();
                ShowToast("Da xay ra loi, vui long thu lai!", "error");
            }
        }
        else
        {
            hocSinhList = new List<HocSinhDTO>();
        }
    }

    private async Task LoadDanhGiaData()
    {
        if (!string.IsNullOrEmpty(SelectedLopId) && !string.IsNullOrEmpty(SelectedMonHoc) && !string.IsNullOrEmpty(SelectedNamHoc))
        {
            try
            {
                var lopIdMon = Convert.ToInt32(SelectedLopId);
                var hocKy = Convert.ToInt32(SelectedHocKy);
                var namHoc = SelectedNamHoc.Split('-')[0];

                var danhGiaList = await DiemService.hGetDanhGiaDinhKy(lopIdMon, hocKy, SelectedMonHoc, namHoc);

                danhGiaCache.Clear();
                foreach (var item in danhGiaList)
                {
                    danhGiaCache[item.GetUniqueKey()] = item;
                }
                Console.WriteLine($"Đã tải {danhGiaList.Count} bản ghi đánh giá cuối kỳ");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Lỗi tải đánh giá: {ex.Message}");
                danhGiaCache.Clear();
                ShowToast("Da xay ra loi, vui long thu lai!", "error");
            }
        }
    }

