    private DiemData.M_DanhGiaDinhKyDTO GetOrCreateDanhGia(string maHocSinh)
    {
        var key = $"{maHocSinh}_{SelectedHocKy}_{SelectedNamHoc.Split('-')[0]}_{SelectedMonHoc}";
        if (danhGiaCache.TryGetValue(key, out var existing)) return existing;

        var newItem = new DiemData.M_DanhGiaDinhKyDTO
        {
            MaHocSinhSo = maHocSinh,
            HocSinhIdSo = maHocSinh,
            HocKy = Convert.ToInt32(SelectedHocKy),
            NamHoc = Convert.ToInt32(SelectedNamHoc.Split('-')[0]),
            MaMonHoc = SelectedMonHoc,
            LopIdMon = Convert.ToInt32(SelectedLop)
        };
        danhGiaCache[key] = newItem;
        return newItem;
    }

