    private async Task SaveDanhGiaInternal(DiemData.M_DanhGiaDinhKyDTO danhGia)
    {
        try
        {
            danhGia.MaSoGd = "79";
            danhGia.IdTruong = thData.truong?.IdTruongSo ?? 0;
            danhGia.MaTruong = maTruongBo;
            danhGia.IdHocSinh = await GetIdHocSinh(danhGia.MaHocSinhSo);
            danhGia.IdPhongGd = 19475;
            danhGia.MaPhongGd = "778";

            var success = await DiemService.hUpsertDanhGiaDinhKy(danhGia);
            if (!success) throw new Exception("Không thể lưu dữ liệu");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi lưu: {ex.Message}");
            throw;
        }
    }

    // ==================== PUBLIC METHODS FOR PARENT ====================
    public async Task SaveChangesAsync()
    {
        if (IsReadOnlyMode) return;

        try
        {
            foreach (var maHs in modifiedStudents.ToList())
            {
                var d = GetOrCreateDanhGia(maHs);
                await SaveDanhGiaInternal(d);
            }
            modifiedStudents.Clear();
            ShowToast("Lưu thành công!", "success");
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
            throw;
        }
    }

    public async Task DiscardChanges()
    {
        await LoadDanhGiaData();
        modifiedStudents.Clear();
    }
