    // ==================== VALIDATION ====================
    private (bool isValid, string errorMessage) ValidateDiem(string value)
    {
        if (string.IsNullOrWhiteSpace(value)) return (true, "");
        value = value.Replace(',', '.');
        if (!double.TryParse(value, NumberStyles.Any, CultureInfo.InvariantCulture, out double diem))
            return (false, "Chỉ được nhập số (0-10)");
        if (diem < 0 || diem > 10) return (false, "Điểm phải từ 0 đến 10");
        if (value.Contains('.') && value.Split('.')[1].Length > 2)
            return (false, "Chỉ được nhập tối đa 2 chữ số thập phân");
        return (true, "");
    }

