    /// <summary>
    /// Lấy chuỗi mã lớp dạng string (VD: "1A") dựa theo SelectedLop (là ID)
    /// </summary>
    private string GetMaLop()
    {
        if (string.IsNullOrEmpty(SelectedLop)) return string.Empty;
        
        // Cách 1: Ưu tiên lấy từ danh sách học sinh đang có
        var lopFromHs = hocSinhList.FirstOrDefault(hs => hs.IdLopBo.ToString() == SelectedLop);
        if (lopFromHs != null && !string.IsNullOrEmpty(lopFromHs.TenLop))
            return lopFromHs.TenLop;

        // Cách 2: Lấy từ danh sách tham chiếu trường học
        var lopDto = thData.danhSachLopList?.FirstOrDefault(l => l.IdLopBo.ToString() == SelectedLop);
        return lopDto?.MaLopBo ?? string.Empty;
    }


