    private string GetFileSize(long bytes)
    {
        string[] sizes = { "B", "KB", "MB" };
        int order = 0;
        double len = bytes;
        while (len >= 1024 && order < sizes.Length - 1) { order++; len /= 1024; }
        return $"{len:0.##} {sizes[order]}";
    }

    private async Task UploadBangDiem()
    {
        if (selectedFile == null) return;

        isUploading = true;
        StateHasChanged();

        try
        {
            var maLop = GetMaLop();
            if (string.IsNullOrEmpty(maLop))
            {
                ShowToast("Không xác định được mã lớp. Vui lòng thử lại.", "warning");
                return;
            }

            using var stream = selectedFile.OpenReadStream(maxAllowedSize: 10 * 1024 * 1024);
            using var ms = new MemoryStream();
            await stream.CopyToAsync(ms);
            var fileBytes = ms.ToArray();

            using var content = new MultipartFormDataContent();
            content.Add(new StringContent(maTruongBo ?? ""), "ma_truong_bo");
            content.Add(new StringContent(SelectedMonHoc ?? ""), "ma_mon_hoc");
            content.Add(new StringContent(maLop), "ma_lop");
            content.Add(new StringContent(GetHocKyId().ToString()), "ma_hocky");
            content.Add(new StringContent(SelectedNamHoc ?? ""), "nam_hoc");
            content.Add(new StringContent("CK"), "dot_danh_gia"); // Đã đổi thành CK

            var fileContent = new ByteArrayContent(fileBytes);
            fileContent.Headers.ContentType = new MediaTypeHeaderValue("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
            content.Add(fileContent, "file", selectedFile.Name);

            string apiUrl = TruongHocData.API_KetNoiSGD + "UploadBangDGDK_C1";
            using var httpClient = new HttpClient();
            httpClient.Timeout = TimeSpan.FromMinutes(10);

            var response = await httpClient.PostAsync(apiUrl, content);
            if (response.IsSuccessStatusCode)
            {
                ShowToast("Tải lên file thành công! Đang cập nhật dữ liệu...", "success");
                await LoadDanhGiaData(); // Reload UI
                CloseUploadModal();
            }
            else
            {
                var error = await response.Content.ReadAsStringAsync();
                ShowToast($"Tải lên thất bại: {error}", "danger");
            }
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
        }
        finally
        {
            isUploading = false;
            StateHasChanged();
        }
    }

    private async Task DownloadBangDiem()
    {
        if (string.IsNullOrEmpty(SelectedLop) || string.IsNullOrEmpty(SelectedMonHoc))
        {
            ShowToast("Vui lòng chọn lớp và môn học trước khi tải file", "warning");
            return;
        }

        isDownloading = true;
        StateHasChanged();

        try
        {
            var maLop = GetMaLop();
            if (string.IsNullOrEmpty(maLop))
            {
                ShowToast("Không xác định được mã lớp. Vui lòng thử lại.", "warning");
                return;
            }

            var request = new
            {
                ma_truong_bo = maTruongBo,
                ma_mon_hoc = SelectedMonHoc,
                ma_lop = maLop,
                ma_hocky = GetHocKyId(),
                nam_hoc = SelectedNamHoc,
                dot_danh_gia = "CK" // Đã đổi thành CK
            };

            var jsonBody = System.Text.Json.JsonSerializer.Serialize(request);
            var httpContent = new StringContent(jsonBody, System.Text.Encoding.UTF8, "application/json");

            string apiUrl = TruongHocData.API_KetNoiSGD + "DownloadMauDGDK_C1";
            using var httpClient = new HttpClient();
            httpClient.Timeout = TimeSpan.FromMinutes(5);

            var response = await httpClient.PostAsync(apiUrl, httpContent);
            if (response.IsSuccessStatusCode)
            {
                var fileBytes = await response.Content.ReadAsByteArrayAsync();

                // Lấy tên file từ header ContentDisposition (nếu có), nếu không tự tạo
                var fileName = $"MauDiem_CK_{maLop}_{SelectedNamHoc}_HK{SelectedHocKy}.xlsx";
                if (response.Content.Headers.ContentDisposition?.FileName != null)
                    fileName = response.Content.Headers.ContentDisposition.FileName.Trim('"');

                // Sử dụng Base64 như luồng GK
                var base64 = Convert.ToBase64String(fileBytes);
                await JS.InvokeVoidAsync("downloadFileFromBase64", fileName, base64, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");

                CloseDownloadModal();
                ShowToast($"Đã tải file mẫu thành công: {fileName}", "success");
            }
            else
            {
                var errorText = await response.Content.ReadAsStringAsync();
                ShowToast($"Tải file thất bại: {response.StatusCode} - {errorText}", "danger");
            }
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
        }
        finally
        {
            isDownloading = false;
            StateHasChanged();
        }
    }

